namespace Inventory;

/// <summary>Allocates available stock across a warehouse's zones.</summary>
public sealed class AllocationCalculator
{
    public IReadOnlyList<string> Allocate(StockItem item, Warehouse warehouse)
    {
        var allocations = new List<string>();
        var remaining = item.OnHand - item.Reserved;

        if (remaining <= 0)
            return allocations;

        foreach (var zone in warehouse.Zones.Where(IsEligible))
        {
            var quantity = CalculatePlacement(remaining, zone.Capacity);
            if (quantity <= 0)
                continue;

            allocations.Add(FormatAllocation(zone.Name, quantity));
            remaining -= quantity;

            if (remaining <= 0)
                break;
        }

        if (remaining > 0)
            allocations.Add(FormatOverflow(remaining));

        return allocations;
    }

    private static bool IsEligible(Zone zone) =>
        zone.Capacity > 0 && !string.IsNullOrEmpty(zone.Name);

    private static int CalculatePlacement(int remaining, int capacity)
    {
        if (remaining > capacity)
            return capacity;

        return remaining > capacity / 2 ? remaining - 1 : remaining;
    }

    private static string FormatAllocation(string name, int quantity) =>
        $"{name}:{quantity}";

    private static string FormatOverflow(int quantity) =>
        $"OVERFLOW:{quantity}";
}
